<script setup lang="ts">import {ref,onMounted} from 'vue';import {instruments} from '../stores/instruments';import {canWrite} from '../stores/auth';import {units} from '../constants/enums';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';const name=ref(''),x=ref(''),y=ref(''),unit=ref('kPa'),description=ref('');const {error,busy,act}=useTask();onMounted(instruments.load);function submit(){act(async()=>{await instruments.create({name:name.value,x_serial:x.value,y_serial:y.value,unit:unit.value,description:description.value});name.value='';x.value='';y.value=''})}</script><template><PageHeading index="02 / 探头组合" title="先确认，被比较的是哪两支探头。" note="探头序列号明确X/Y方向。回归和差值定义都依赖此方向；本系统不向设备写入校准参数。"/><div class="two-col"><section><article v-for="r in instruments.items.value" :key="r.id" class="instrument-row"><p class="eyebrow">INSTRUMENT PAIR</p><h2>{{r.name}}</h2><div class="instrument-line"><div><small>X / 对照侧</small><strong>{{r.x_serial}}</strong></div><i>↔</i><div><small>Y / 比对侧</small><strong>{{r.y_serial}}</strong></div></div><p>单位 {{r.unit}} · {{r.description}}</p></article></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>登记探头组合</h2><label>组合名称<input v-model="name" required minlength="2"></label><label>X探头序列号<input v-model="x" required minlength="2"></label><label>Y探头序列号<input v-model="y" required minlength="2"></label><label>共同单位<select v-model="unit"><option v-for="u in units" :key="u">{{u}}</option></select></label><label>重复测量依据<textarea v-model="description" rows="4"></textarea></label><Notice :message="error"/><button :disabled="busy">保存探头组合</button></form></div></template>
